// Bab 4 Data Modeling: membangun tabel fakta (lookup surrogate key, point-in-time join SCD2, unknown member,
// accumulating snapshot, mart ringkasan bulanan, rekonsiliasi ke sumber).
// Setiap latihan dijalankan di transaksi yang dibatalkan, jadi dimensi dan fakta dibuat ulang di setup setiap contoh dan soal.

// Dimensi dari bab model-03, disalin persis dari solusi soal build di sana (model-03-04, -07, -13).
const DIM_DATE = `create schema dw;
create table dw.dim_date (
  date_key integer primary key,
  full_date date not null unique,
  year integer not null,
  quarter integer not null,
  month integer not null,
  month_name text not null,
  day_of_month integer not null,
  day_of_week integer not null,
  day_name text not null,
  is_weekend boolean not null
);
insert into dw.dim_date
with tanggal as (
  select g::date as d
  from generate_series(date '2024-01-01', date '2025-12-31', interval '1 day') as g
)
select to_char(d, 'YYYYMMDD')::integer, d,
       extract(year from d), extract(quarter from d), extract(month from d),
       to_char(d, 'FMMonth'), extract(day from d),
       extract(isodow from d), to_char(d, 'FMDay'),
       extract(isodow from d) in (6, 7)
from tanggal;`;

const DIM_PRODUCT = `create table dw.dim_product (
  product_sk integer generated by default as identity primary key,
  product_id integer not null unique,
  sku text not null,
  product_name text not null,
  brand text not null,
  category_name text not null,
  parent_category_name text not null,
  is_active boolean not null
);
insert into dw.dim_product (product_sk, product_id, sku, product_name, brand, category_name, parent_category_name, is_active)
values (-1, -1, 'Tidak diketahui', 'Produk tidak diketahui', 'Tidak diketahui', 'Tidak diketahui', 'Tidak diketahui', false);
insert into dw.dim_product (product_id, sku, product_name, brand, category_name, parent_category_name, is_active)
select p.product_id, p.sku, p.product_name, p.brand, c.category_name, pc.category_name, p.is_active
from app.products as p
join app.categories as c on c.category_id = p.category_id
join app.categories as pc on pc.category_id = c.parent_id
order by p.product_id
on conflict (product_id) do update
set sku = excluded.sku,
    product_name = excluded.product_name,
    brand = excluded.brand,
    category_name = excluded.category_name,
    parent_category_name = excluded.parent_category_name,
    is_active = excluded.is_active;`;

const DIM_CUSTOMER = `create table dw.dim_customer (
  customer_sk integer generated always as identity primary key,
  customer_id integer not null,
  full_name text not null,
  city_id integer not null,
  city_name text not null,
  segment text not null,
  valid_from date not null,
  valid_to date not null,
  is_current boolean not null
);
insert into dw.dim_customer (customer_id, full_name, city_id, city_name, segment, valid_from, valid_to, is_current)
with potret as (
  select snapshot_date, customer_id, full_name, city_id, segment,
         lag(city_id) over (partition by customer_id order by snapshot_date) as kota_sebelumnya,
         lag(segment) over (partition by customer_id order by snapshot_date) as segmen_sebelumnya
  from raw.customer_snapshot
),
awal_versi as (
  select snapshot_date, customer_id, full_name, city_id, segment
  from potret
  where kota_sebelumnya is null
     or city_id <> kota_sebelumnya
     or segment <> segmen_sebelumnya
),
versi as (
  select a.*,
         row_number() over (partition by customer_id order by snapshot_date) as nomor_versi,
         lead(snapshot_date) over (partition by customer_id order by snapshot_date) as awal_berikutnya
  from awal_versi as a
)
select v.customer_id, v.full_name, v.city_id, ci.city_name, v.segment,
       case when v.nomor_versi = 1 then cu.signup_date else v.snapshot_date end,
       coalesce(v.awal_berikutnya - 1, date '9999-12-31'),
       v.awal_berikutnya is null
from versi as v
join app.cities as ci on ci.city_id = v.city_id
join app.customers as cu on cu.customer_id = v.customer_id
order by v.customer_id, v.snapshot_date;`;

// Tambahan bab ini: baris khusus -1 di dimensi tanggal ("belum terjadi") dan di dimensi pelanggan (unknown member).
const EXTRA_ROWS = `insert into dw.dim_date
values (-1, date '9999-12-31', 9999, 4, 12, 'Belum terjadi', 31, 5, 'Belum terjadi', false);
insert into dw.dim_customer (customer_sk, customer_id, full_name, city_id, city_name, segment, valid_from, valid_to, is_current)
overriding system value
values (-1, -1, 'Pelanggan tidak diketahui', -1, 'Tidak diketahui', 'Tidak diketahui', date '1900-01-01', date '9999-12-31', true);`;

const DIMS = `${DIM_DATE}\n${DIM_PRODUCT}\n${DIM_CUSTOMER}\n${EXTRA_ROWS}`;

// Skenario soal unknown member: dimensi produk seolah terakhir dimuat 31 Mei 2025.
const STALE_PRODUCT = `delete from dw.dim_product
where product_id in (select product_id from app.products where created_at >= '2025-06-01');`;

const FACT_ORDER_LINE = `create table dw.fact_order_line (
  order_id integer not null,
  line_no integer not null,
  order_date_key integer not null references dw.dim_date (date_key),
  customer_sk integer not null references dw.dim_customer (customer_sk),
  product_sk integer not null references dw.dim_product (product_sk),
  qty integer not null,
  gross_amount numeric(14,2) not null,
  discount numeric(14,2) not null,
  net_amount numeric(14,2) not null,
  primary key (order_id, line_no)
);
insert into dw.fact_order_line
  (order_id, line_no, order_date_key, customer_sk, product_sk, qty, gross_amount, discount, net_amount)
select oi.order_id, oi.line_no,
       coalesce(d.date_key, -1),
       coalesce(c.customer_sk, -1),
       coalesce(p.product_sk, -1),
       oi.qty,
       oi.qty * oi.unit_price,
       oi.discount,
       oi.qty * oi.unit_price - oi.discount
from app.order_items as oi
join app.orders as o on o.order_id = oi.order_id
left join dw.dim_date as d on d.full_date = o.order_ts::date
left join dw.dim_customer as c
  on c.customer_id = o.customer_id
 and o.order_ts::date between c.valid_from and c.valid_to
left join dw.dim_product as p on p.product_id = oi.product_id;`;

const FACT_PAYMENT = `create table dw.fact_payment (
  payment_id integer primary key,
  order_id integer not null,
  paid_date_key integer not null references dw.dim_date (date_key),
  customer_sk integer not null references dw.dim_customer (customer_sk),
  method text not null,
  status text not null,
  amount numeric(12,2) not null
);
insert into dw.fact_payment (payment_id, order_id, paid_date_key, customer_sk, method, status, amount)
select pa.payment_id, pa.order_id,
       coalesce(d.date_key, -1),
       coalesce(c.customer_sk, -1),
       pa.method, pa.status, pa.amount
from app.payments as pa
join app.orders as o on o.order_id = pa.order_id
left join dw.dim_date as d on d.full_date = pa.paid_ts::date
left join dw.dim_customer as c
  on c.customer_id = o.customer_id
 and pa.paid_ts::date between c.valid_from and c.valid_to;`;

// Satu baris per pesanan dengan semua tonggaknya, dipakai untuk muatan pertama dan untuk MERGE.
const FUL_SELECT = `select o.order_id,
       coalesce(c.customer_sk, -1) as customer_sk,
       coalesce(tp.date_key, -1) as order_date_key,
       coalesce(tk.date_key, -1) as shipped_date_key,
       coalesce(tt.date_key, -1) as delivered_date_key,
       coalesce(tr.date_key, -1) as returned_date_key,
       s.shipped_ts::date - o.order_ts::date as days_to_ship,
       s.delivered_ts::date - s.shipped_ts::date as days_in_transit,
       s.delivered_ts::date - o.order_ts::date as days_to_deliver
from app.orders as o
left join app.shipments as s on s.order_id = o.order_id
left join (
  select order_id, min(return_ts) as first_return_ts
  from app.returns
  group by order_id
) as r on r.order_id = o.order_id
left join dw.dim_customer as c
  on c.customer_id = o.customer_id
 and o.order_ts::date between c.valid_from and c.valid_to
left join dw.dim_date as tp on tp.full_date = o.order_ts::date
left join dw.dim_date as tk on tk.full_date = s.shipped_ts::date
left join dw.dim_date as tt on tt.full_date = s.delivered_ts::date
left join dw.dim_date as tr on tr.full_date = r.first_return_ts::date`;

const FACT_FULFILLMENT = `create table dw.fact_fulfillment (
  order_id integer primary key,
  customer_sk integer not null references dw.dim_customer (customer_sk),
  order_date_key integer not null references dw.dim_date (date_key),
  shipped_date_key integer not null references dw.dim_date (date_key),
  delivered_date_key integer not null references dw.dim_date (date_key),
  returned_date_key integer not null references dw.dim_date (date_key),
  days_to_ship integer,
  days_in_transit integer,
  days_to_deliver integer
);
insert into dw.fact_fulfillment
  (order_id, customer_sk, order_date_key, shipped_date_key, delivered_date_key, returned_date_key,
   days_to_ship, days_in_transit, days_to_deliver)
${FUL_SELECT};`;

// Dua tonggak baru di sumber, untuk contoh dan soal pembaruan accumulating snapshot.
const NEW_MILESTONES = `update app.shipments set delivered_ts = timestamp '2025-11-01 14:00:00' where order_id = 111920;
update app.orders set status = 'completed', updated_at = timestamp '2025-11-01 14:00:00' where order_id = 111920;
insert into app.shipments (order_id, courier, shipped_ts, delivered_ts)
values (111983, 'JNE', timestamp '2025-11-01 09:00:00', null);
update app.orders set status = 'shipped', updated_at = timestamp '2025-11-01 09:00:00' where order_id = 111983;`;

const MERGE_FULFILLMENT = `merge into dw.fact_fulfillment as t
using (
${FUL_SELECT}
) as src
on t.order_id = src.order_id
when matched then
  update set customer_sk = src.customer_sk,
             order_date_key = src.order_date_key,
             shipped_date_key = src.shipped_date_key,
             delivered_date_key = src.delivered_date_key,
             returned_date_key = src.returned_date_key,
             days_to_ship = src.days_to_ship,
             days_in_transit = src.days_in_transit,
             days_to_deliver = src.days_to_deliver
when not matched then
  insert (order_id, customer_sk, order_date_key, shipped_date_key, delivered_date_key, returned_date_key,
          days_to_ship, days_in_transit, days_to_deliver)
  values (src.order_id, src.customer_sk, src.order_date_key, src.shipped_date_key, src.delivered_date_key,
          src.returned_date_key, src.days_to_ship, src.days_in_transit, src.days_to_deliver);`;

const MART = `create schema mart;
create table mart.sales_monthly (
  year integer not null,
  month integer not null,
  order_count integer not null,
  customer_count integer not null,
  qty integer not null,
  gross_amount numeric(14,2) not null,
  discount numeric(14,2) not null,
  net_amount numeric(14,2) not null,
  primary key (year, month)
);
insert into mart.sales_monthly (year, month, order_count, customer_count, qty, gross_amount, discount, net_amount)
select d.year, d.month,
       count(distinct f.order_id),
       count(distinct c.customer_id),
       sum(f.qty),
       sum(f.gross_amount),
       sum(f.discount),
       sum(f.net_amount)
from dw.fact_order_line as f
join dw.dim_date as d on d.date_key = f.order_date_key
join dw.dim_customer as c on c.customer_sk = f.customer_sk
group by d.year, d.month;`;

// Untuk setup contoh dan soal lanjutan, REFERENCES dibuang supaya pemuatan lebih cepat di browser (pemeriksaan
// foreign key per baris memakan waktu paling banyak). Isi tabelnya sama persis.
const noFk = (sql) => sql.replace(/ references dw\.dim_\w+ \(\w+\)/g, "");
const WITH_ORDER_LINE = `${DIMS}\n${noFk(FACT_ORDER_LINE)}`;
const WITH_FULFILLMENT = `${DIMS}\n${noFk(FACT_FULFILLMENT)}`;

// Verify: hanya dibaca mesin. Semua pemeriksaan dihitung ulang dari sumber app.*.
const VERIFY_ORDER_LINE = `select count(*) as baris,
       count(*) - (select count(*) from app.order_items) as selisih_baris,
       count(distinct (f.order_id, f.line_no)) as grain_unik,
       count(*) filter (where f.order_date_key is null or f.customer_sk is null or f.product_sk is null) as key_kosong,
       sum(f.qty) as qty, sum(f.gross_amount) as gross, sum(f.discount) as diskon, sum(f.net_amount) as bersih,
       count(*) filter (where f.product_sk = -1) as produk_unknown,
       count(*) filter (where p.product_id = oi.product_id) as produk_cocok,
       count(*) filter (where c.customer_id = o.customer_id and o.order_ts::date between c.valid_from and c.valid_to) as versi_cocok,
       count(*) filter (where dd.full_date = o.order_ts::date) as tanggal_cocok,
       count(*) filter (where f.qty = oi.qty and f.gross_amount = oi.qty * oi.unit_price and f.discount = oi.discount
                          and f.net_amount = oi.qty * oi.unit_price - oi.discount) as measure_cocok,
       (select count(*) from pg_constraint where conrelid = 'dw.fact_order_line'::regclass and contype = 'p') as primary_key
from dw.fact_order_line as f
left join app.order_items as oi on oi.order_id = f.order_id and oi.line_no = f.line_no
left join app.orders as o on o.order_id = f.order_id
left join dw.dim_product as p on p.product_sk = f.product_sk
left join dw.dim_customer as c on c.customer_sk = f.customer_sk
left join dw.dim_date as dd on dd.date_key = f.order_date_key;`;

const VERIFY_PAYMENT = `select f.status, count(*) as baris, count(distinct f.payment_id) as grain_unik,
       count(*) filter (where f.paid_date_key is null or f.customer_sk is null) as key_kosong,
       sum(f.amount) as amount,
       count(*) filter (where f.order_id = pa.order_id and f.method = pa.method and f.status = pa.status and f.amount = pa.amount) as isi_cocok,
       count(*) filter (where dd.full_date = pa.paid_ts::date) as tanggal_cocok,
       count(*) filter (where c.customer_id = o.customer_id and pa.paid_ts::date between c.valid_from and c.valid_to) as versi_cocok,
       (select count(*) from app.payments) as baris_sumber,
       (select count(*) from pg_constraint where conrelid = 'dw.fact_payment'::regclass and contype = 'p') as primary_key
from dw.fact_payment as f
left join app.payments as pa on pa.payment_id = f.payment_id
left join app.orders as o on o.order_id = pa.order_id
left join dw.dim_customer as c on c.customer_sk = f.customer_sk
left join dw.dim_date as dd on dd.date_key = f.paid_date_key
group by f.status;`;

const VERIFY_FULFILLMENT = `select count(*) as baris,
       count(*) - (select count(*) from app.orders) as selisih_baris,
       count(distinct f.order_id) as grain_unik,
       count(*) filter (where f.customer_sk is null or f.order_date_key is null or f.shipped_date_key is null
                          or f.delivered_date_key is null or f.returned_date_key is null) as key_kosong,
       count(*) filter (where f.shipped_date_key = -1) as belum_dikirim,
       count(*) filter (where f.delivered_date_key = -1) as belum_diterima,
       count(*) filter (where f.returned_date_key = -1) as tanpa_pengembalian,
       count(*) filter (where c.customer_id = o.customer_id and o.order_ts::date between c.valid_from and c.valid_to) as versi_cocok,
       count(*) filter (where tp.full_date = o.order_ts::date) as tgl_pesan_cocok,
       count(*) filter (where tk.full_date = s.shipped_ts::date or (s.order_id is null and f.shipped_date_key = -1)) as tgl_kirim_cocok,
       count(*) filter (where tt.full_date = s.delivered_ts::date or (s.delivered_ts is null and f.delivered_date_key = -1)) as tgl_terima_cocok,
       count(*) filter (where tr.full_date = rr.first_return_date or (rr.order_id is null and f.returned_date_key = -1)) as tgl_kembali_cocok,
       count(f.days_to_ship) as isi_days_to_ship, sum(f.days_to_ship) as total_days_to_ship,
       count(f.days_in_transit) as isi_days_in_transit, sum(f.days_in_transit) as total_days_in_transit,
       count(f.days_to_deliver) as isi_days_to_deliver, sum(f.days_to_deliver) as total_days_to_deliver,
       count(*) filter (where f.days_to_ship is not distinct from s.shipped_ts::date - o.order_ts::date
                          and f.days_in_transit is not distinct from s.delivered_ts::date - s.shipped_ts::date
                          and f.days_to_deliver is not distinct from s.delivered_ts::date - o.order_ts::date) as durasi_cocok
from dw.fact_fulfillment as f
left join app.orders as o on o.order_id = f.order_id
left join app.shipments as s on s.order_id = f.order_id
left join (select order_id, min(return_ts)::date as first_return_date from app.returns group by order_id) as rr on rr.order_id = f.order_id
left join dw.dim_customer as c on c.customer_sk = f.customer_sk
left join dw.dim_date as tp on tp.date_key = f.order_date_key
left join dw.dim_date as tk on tk.date_key = f.shipped_date_key
left join dw.dim_date as tt on tt.date_key = f.delivered_date_key
left join dw.dim_date as tr on tr.date_key = f.returned_date_key;`;

const VERIFY_MART = `select year, month, order_count, customer_count, qty, gross_amount, discount, net_amount
from mart.sales_monthly;`;

